import { BRAND_LOGOS, BRAND_NAME } from "@/lib/brand";

/**
 * BrandMark — renders the mark-only logo from the public asset
 * generated by `scripts/build-brand-svgs.mjs`. Use this anywhere a
 * standalone glyph is needed (header, sidebar, ticket bar).
 *
 * Pass `mono` to render the single-color (currentColor) variant —
 * useful inside dark surfaces or when the mark sits next to coloured
 * text that should drive the fill.
 */
export default function BrandMark({
  size = 40,
  mono = false,
  className,
  title
}: {
  size?: number;
  mono?: boolean;
  className?: string;
  title?: string;
}) {
  // Mark is wider than tall (~410×280). Match that aspect so the icon
  // doesn't get squashed when callers pass a single `size`.
  const aspect = 410 / 280;
  const height = size;
  const width  = Math.round(size * aspect);
  return (
    /* eslint-disable-next-line @next/next/no-img-element */
    <img
      src={mono ? BRAND_LOGOS.markMono : BRAND_LOGOS.mark}
      alt={title ?? BRAND_NAME}
      width={width}
      height={height}
      className={className}
      style={{ display: "inline-block" }}
    />
  );
}
